"use client";

import { useState, useRef, useEffect } from "react";
import Container from "@/components/Container";
import { Copy, Download, QrCode, Share2, Sparkles, Wand2, Upload, Trash2 } from "lucide-react";

type DotType = 'square' | 'dots' | 'rounded' | 'extra-rounded' | 'classy' | 'classy-rounded';
type CornerSquareType = 'square' | 'dot' | 'extra-rounded';

const FG_PRESETS = ['#000000', '#27272a', '#1e3a8a', '#4c1d95', '#be123c', '#047857'];
const BG_PRESETS = ['#ffffff', '#f4f4f5', '#fffbeb', '#f0fdf4', '#eff6ff', '#faf5ff'];

export default function QRGeneratorPage() {
    const [url, setUrl] = useState("https://assetnest.design");
    const [fgColor, setFgColor] = useState("#000000");
    const [bgColor, setBgColor] = useState("#ffffff");

    // New Advanced Options
    const [dotType, setDotType] = useState<DotType>("square");
    const [cornerSquareType, setCornerSquareType] = useState<CornerSquareType>("square");
    const [logo, setLogo] = useState<string | null>(null);

    const qrRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const qrCodeInstance = useRef<any>(null);

    // Initialize QR Code Styling library dynamically
    useEffect(() => {
        let isMounted = true;

        const initQR = async () => {
            const QRCodeStyling = (await import("qr-code-styling")).default;
            if (!isMounted) return;

            const qrCode = new QRCodeStyling({
                width: 512,
                height: 512,
                type: "svg",
                data: url,
                image: logo || undefined,
                margin: 10,
                qrOptions: {
                    typeNumber: 0,
                    mode: "Byte",
                    errorCorrectionLevel: "H"
                },
                imageOptions: {
                    hideBackgroundDots: true,
                    imageSize: 0.4,
                    margin: 5,
                    crossOrigin: "anonymous",
                },
                dotsOptions: {
                    color: fgColor,
                    type: dotType
                },
                backgroundOptions: {
                    color: bgColor,
                },
                cornersSquareOptions: {
                    color: fgColor,
                    type: cornerSquareType,
                }
            });

            qrCodeInstance.current = qrCode;

            if (qrRef.current) {
                qrRef.current.innerHTML = "";
                qrCode.append(qrRef.current);
            }
        };

        initQR();

        return () => { isMounted = false; };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Update QR Code when state changes
    useEffect(() => {
        if (!qrCodeInstance.current) return;

        qrCodeInstance.current.update({
            data: url,
            image: logo || undefined,
            dotsOptions: {
                color: fgColor,
                type: dotType
            },
            backgroundOptions: {
                color: bgColor,
            },
            cornersSquareOptions: {
                type: cornerSquareType,
                color: fgColor,
            }
        });
    }, [url, fgColor, bgColor, dotType, cornerSquareType, logo]);

    const downloadQR = async () => {
        if (!qrCodeInstance.current) return;

        // Spawn a temporary, massive high-res QR code just for the download
        const QRCodeStyling = (await import("qr-code-styling")).default;

        const highResQrCode = new QRCodeStyling({
            width: 2048,
            height: 2048,
            type: "canvas", // Canvas is often better for a direct PNG export
            data: url,
            image: logo || undefined,
            margin: 20, // Give it a nice thick quiet zone for scanning
            qrOptions: {
                typeNumber: 0,
                mode: "Byte",
                errorCorrectionLevel: "H"
            },
            imageOptions: {
                hideBackgroundDots: true,
                imageSize: 0.4,
                margin: 10,
                crossOrigin: "anonymous",
            },
            dotsOptions: {
                color: fgColor,
                type: dotType
            },
            backgroundOptions: {
                color: bgColor,
            },
            cornersSquareOptions: {
                color: fgColor,
                type: cornerSquareType,
            }
        });

        highResQrCode.download({ name: "assetnest-highres-qr", extension: "png" });
    };

    const copyUrl = () => {
        navigator.clipboard.writeText(url);
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                setLogo(event.target?.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const removeLogo = () => {
        setLogo(null);
        if (fileInputRef.current) {
            fileInputRef.current.value = '';
        }
    };

    return (
        <div className="py-24 min-h-screen bg-black">
            <Container>
                <header className="mb-16 text-center">
                    <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/5 border border-white/10 mb-6">
                        <QrCode size={12} className="text-zinc-500" />
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500">Pro Utilities</span>
                    </div>
                    <h1 className="text-5xl md:text-7xl font-black tracking-tighter uppercase mb-4 text-white leading-none">
                        Advanced <span className="italic text-zinc-700">QR Engine</span>
                    </h1>
                    <p className="text-sm text-zinc-500 max-w-xl mx-auto font-medium leading-relaxed">
                        Generate fully brandable QR codes with custom styling, edge types, and embedded logos.
                    </p>
                </header>

                <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-12">
                    {/* Input Controls (Spans 8 cols) */}
                    <div className="lg:col-span-7 space-y-6">
                        <div className="p-8 bg-zinc-900/50 border border-zinc-800 rounded-[2.5rem] shadow-2xl backdrop-blur-sm">
                            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-6 flex items-center gap-2">
                                <Wand2 size={12} /> Configuration Options
                            </h3>

                            <div className="space-y-8">
                                {/* Destination URL */}
                                <div>
                                    <label className="block text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-3">Destination URL</label>
                                    <div className="relative">
                                        <input
                                            type="text"
                                            value={url}
                                            onChange={(e) => setUrl(e.target.value)}
                                            className="w-full bg-black border border-zinc-800 focus:border-white transition-all px-5 py-4 rounded-2xl text-sm font-medium outline-none text-zinc-200"
                                            placeholder="Enter your link here..."
                                        />
                                        <button
                                            onClick={copyUrl}
                                            className="absolute right-4 top-1/2 -translate-y-1/2 p-2 text-zinc-600 hover:text-white transition-colors"
                                        >
                                            <Copy size={16} />
                                        </button>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4 border-t border-zinc-800">
                                    {/* Styling: Dots */}
                                    <div>
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-3">QR Pattern Style</label>
                                        <select
                                            value={dotType}
                                            onChange={(e) => setDotType(e.target.value as DotType)}
                                            className="w-full bg-black border border-zinc-800 px-4 py-3 rounded-xl text-xs font-semibold text-zinc-300 outline-none focus:border-white transition-all appearance-none"
                                        >
                                            <option value="square">Standard Squares</option>
                                            <option value="dots">Dots</option>
                                            <option value="rounded">Rounded</option>
                                            <option value="extra-rounded">Extra Rounded</option>
                                            <option value="classy">Classy</option>
                                            <option value="classy-rounded">Classy Rounded</option>
                                        </select>
                                    </div>

                                    {/* Styling: Corners */}
                                    <div>
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-3">Corner Frame Style</label>
                                        <select
                                            value={cornerSquareType}
                                            onChange={(e) => setCornerSquareType(e.target.value as CornerSquareType)}
                                            className="w-full bg-black border border-zinc-800 px-4 py-3 rounded-xl text-xs font-semibold text-zinc-300 outline-none focus:border-white transition-all appearance-none"
                                        >
                                            <option value="square">Standard</option>
                                            <option value="dot">Dot / Circular</option>
                                            <option value="extra-rounded">Extra Rounded</option>
                                        </select>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4 border-t border-zinc-800">
                                    <div className="col-span-1 md:col-span-2 space-y-4 pt-4">
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-2">QR Colors</label>

                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-black border border-zinc-800 p-5 rounded-[1.5rem]">
                                            {/* Foreground */}
                                            <div className="space-y-4">
                                                <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest block">Foreground (Dots)</span>
                                                <div className="flex gap-2">
                                                    {FG_PRESETS.map(color => (
                                                        <button
                                                            key={color}
                                                            onClick={() => setFgColor(color)}
                                                            className={`w-6 h-6 rounded-full border-2 transition-all ${fgColor === color ? 'border-white scale-110 shadow-[0_0_10px_rgba(255,255,255,0.3)]' : 'border-transparent hover:scale-105'}`}
                                                            style={{ backgroundColor: color }}
                                                            title={color}
                                                        />
                                                    ))}
                                                </div>
                                                <div className="flex items-center gap-3">
                                                    <div className="relative w-8 h-8 rounded-lg overflow-hidden shrink-0 border border-zinc-700 shadow-inner">
                                                        <input
                                                            type="color"
                                                            value={fgColor}
                                                            onChange={(e) => setFgColor(e.target.value)}
                                                            className="absolute -inset-4 w-16 h-16 cursor-pointer"
                                                        />
                                                    </div>
                                                    <input
                                                        type="text"
                                                        value={fgColor.toUpperCase()}
                                                        onChange={(e) => setFgColor(e.target.value)}
                                                        className="bg-zinc-900 border border-zinc-800 px-3 py-2 rounded-xl text-xs font-mono text-zinc-300 w-24 focus:border-white transition-all outline-none"
                                                    />
                                                </div>
                                            </div>

                                            {/* Background */}
                                            <div className="space-y-4">
                                                <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest block">Background</span>
                                                <div className="flex gap-2">
                                                    {BG_PRESETS.map(color => (
                                                        <button
                                                            key={color}
                                                            onClick={() => setBgColor(color)}
                                                            className={`w-6 h-6 rounded-full border-2 transition-all ${bgColor === color ? 'border-zinc-400 scale-110 shadow-[0_0_10px_rgba(255,255,255,0.2)]' : 'border-zinc-200 hover:scale-105 shadow-sm'}`}
                                                            style={{ backgroundColor: color }}
                                                            title={color}
                                                        />
                                                    ))}
                                                </div>
                                                <div className="flex items-center gap-3">
                                                    <div className="relative w-8 h-8 rounded-lg overflow-hidden shrink-0 border border-zinc-700 shadow-inner">
                                                        <input
                                                            type="color"
                                                            value={bgColor}
                                                            onChange={(e) => setBgColor(e.target.value)}
                                                            className="absolute -inset-4 w-16 h-16 cursor-pointer"
                                                        />
                                                    </div>
                                                    <input
                                                        type="text"
                                                        value={bgColor.toUpperCase()}
                                                        onChange={(e) => setBgColor(e.target.value)}
                                                        className="bg-zinc-900 border border-zinc-800 px-3 py-2 rounded-xl text-xs font-mono text-zinc-300 w-24 focus:border-white transition-all outline-none"
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Logo Upload */}
                                    <div className="space-y-4">
                                        <label className="block text-[10px] font-black uppercase tracking-widest text-zinc-400 mb-1">Center Logo</label>

                                        <div className="flex items-center gap-3">
                                            <input
                                                type="file"
                                                accept="image/*"
                                                className="hidden"
                                                ref={fileInputRef}
                                                onChange={handleLogoUpload}
                                            />
                                            <button
                                                onClick={() => fileInputRef.current?.click()}
                                                className="flex-1 flex items-center justify-center gap-2 bg-black border border-zinc-800 hover:border-zinc-500 text-zinc-300 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all"
                                            >
                                                <Upload size={14} /> Upload Image
                                            </button>

                                            {logo && (
                                                <button
                                                    onClick={removeLogo}
                                                    className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500/20 transition-all border border-red-500/20"
                                                    title="Remove Logo"
                                                >
                                                    <Trash2 size={16} />
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-6 border border-zinc-900 rounded-3xl bg-zinc-900/30">
                            <div className="flex items-start gap-4">
                                <div className="p-3 bg-zinc-900 rounded-2xl shrink-0">
                                    <Sparkles size={16} className="text-zinc-500" />
                                </div>
                                <div>
                                    <h4 className="text-xs font-bold text-white mb-2 uppercase tracking-wide">Pro Tip</h4>
                                    <p className="text-xs text-zinc-500 leading-relaxed font-medium">
                                        When adding a center logo, ensure you pick a high-contrast Foreground color. If the QR code becomes unscannable, try reverting the pattern to "Standard Squares" for maximum camera compatibility.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Preview Area (Spans 5 cols) */}
                    <div className="lg:col-span-5 flex flex-col items-center justify-start lg:pt-4">
                        <div className="relative group w-full max-w-sm">
                            {/* Decorative blur */}
                            <div className="absolute inset-0 bg-white/5 blur-[100px] rounded-[4rem] group-hover:bg-white/10 transition-all duration-700" />

                            <div className="relative p-8 md:p-10 bg-zinc-900 border border-zinc-800 rounded-[3rem] shadow-[0_40px_100px_rgba(0,0,0,0.5)]">

                                <div className="flex items-center justify-center bg-white p-4 rounded-[1.5rem] overflow-hidden">
                                    {/* QR Code Canvas injected here */}
                                    <div ref={qrRef} className="w-full flex justify-center [&>svg]:max-w-full [&>svg]:h-auto" />
                                </div>

                                <div className="mt-10 flex flex-col gap-3">
                                    <button
                                        onClick={downloadQR}
                                        className="w-full flex items-center justify-center gap-3 bg-white text-black py-4 rounded-xl text-[11px] font-black uppercase tracking-[0.2em] hover:bg-zinc-200 transition-all active:scale-[0.98] shadow-xl"
                                    >
                                        <Download size={14} /> Export High-Res PNG
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </Container>
        </div>
    );
}
